// For each particle in the range
for (size_t idx = start; idx < end; idx++) {
    // Get current particle position
    const float px = particles[idx].x;
    const float py = particles[idx].y;
    const float pz = particles[idx].z;

    // Calculate cell coordinates for the particle
    const int cellX = static_cast<int>(px);
    const int cellY = static_cast<int>(py);
    const int cellZ = static_cast<int>(pz);

    // Initialize density with self-contribution
    float density = selfDens;

    // Iterate through 27 neighboring cells
    for (int dx = -1; dx <= 1; dx++) {
        for (int dy = -1; dy <= 1; dy++) {
            for (int dz = -1; dz <= 1; dz++) {
                // Look up neighbors in each neighboring cell using particleTable
                const uint32_t neighborCell = hash(cellX + dx, cellY + dy, cellZ + dz);
                uint32_t neighborIdx = particleTable[neighborCell];

                // Process all particles in this cell
                while (neighborIdx != UINT32_MAX) {
                    if (neighborIdx != idx) {
                        // Calculate distance to neighbor
                        const float rx = px - particles[neighborIdx].x;
                        const float ry = py - particles[neighborIdx].y;
                        const float rz = pz - particles[neighborIdx].z;
                        const float r2 = rx*rx + ry*ry + rz*rz;

                        // Apply poly6 kernel if within smoothing radius
                        if (r2 < h2) {
                            const float diff = h2 - r2;
                            density += mass * poly6 * diff * diff * diff;
                        }
                    }
                    neighborIdx = particles[neighborIdx].next;
                }
            }
        }
    }

    // Store computed density and pressure
    particles[idx].density = density;
    particles[idx].pressure = gasConstant * (density - restDensity);
}

